// Copia as 9 tabelas do comparaevs do Supabase pro Neon. Sem FK real entre
// elas (conferido antes de escrever o schema), então a ordem das tabelas
// abaixo não importa pra integridade — só pra legibilidade do log.
//
// Depois de inserir com os ids originais (bigint identity aceita valor
// explícito com GENERATED BY DEFAULT), a sequência interna de cada tabela
// precisa ser avançada pro maior id migrado — senão a primeira linha nova
// criada ao vivo (um clique, um lead) tentaria reusar um id que já existe e
// colidiria com a PRIMARY KEY. Mesma lição do protocol_seq no gramaldo26.
//
// node --env-file=.env.local scripts/migrate-data-to-neon.mjs
import { createClient } from "@supabase/supabase-js";
import pg from "pg";

// service role, não a anon key: leads_propostas/leads_instalacao/
// newsletter_leads/sugestoes_correcao só têm policy de INSERT pra anon,
// sem SELECT — a chave pública não devolve essas linhas de volta.
const supabase = createClient(process.env.NEXT_PUBLIC_SUPABASE_URL, process.env.SUPABASE_SERVICE_ROLE_KEY);

const TABLES = [
  "pbe_veiculos_eletricos",
  "pbe_motos_eletricas",
  "carregadores",
  "patrocinadores_slots",
  "eventos_cliques",
  "leads_propostas",
  "leads_instalacao",
  "newsletter_leads",
  "sugestoes_correcao",
];

// Tabelas com PK bigint identity — precisam do ajuste de sequência no final.
// carregadores usa uuid (gen_random_uuid), não entra aqui.
const BIGINT_ID_TABLES = new Set([
  "pbe_veiculos_eletricos",
  "pbe_motos_eletricas",
  "patrocinadores_slots",
  "eventos_cliques",
  "leads_propostas",
  "leads_instalacao",
  "newsletter_leads",
  "sugestoes_correcao",
]);

const PAGE_SIZE = 1000;

async function fetchAllRows(table) {
  const rows = [];
  let from = 0;
  for (;;) {
    const { data, error } = await supabase.from(table).select("*").range(from, from + PAGE_SIZE - 1);
    if (error) throw new Error(`${table}: ${error.message}`);
    rows.push(...data);
    if (data.length < PAGE_SIZE) break;
    from += PAGE_SIZE;
  }
  return rows;
}

async function migrateTable(client, table) {
  const rows = await fetchAllRows(table);
  if (rows.length === 0) {
    console.log(`${table}: 0 linhas na origem`);
    return { table, source: 0, inserted: 0 };
  }

  const columns = Object.keys(rows[0]);
  const colList = columns.map((c) => `"${c}"`).join(", ");

  let inserted = 0;
  for (const row of rows) {
    const values = columns.map((c) => row[c]);
    const placeholders = columns.map((_, i) => `$${i + 1}`).join(", ");
    const result = await client.query(
      `insert into public.${table} (${colList}) values (${placeholders}) on conflict do nothing`,
      values
    );
    inserted += result.rowCount;
  }
  console.log(`${table}: ${rows.length} na origem -> ${inserted} inseridas no Neon`);
  return { table, source: rows.length, inserted };
}

async function main() {
  const client = new pg.Client({ connectionString: process.env.NEON_DATABASE_URL });
  await client.connect();

  const summary = [];
  for (const table of TABLES) {
    summary.push(await migrateTable(client, table));
  }

  console.log("\n--- Ajustando sequências (evita colisão de id em linha nova) ---");
  for (const table of BIGINT_ID_TABLES) {
    await client.query(
      `select setval(pg_get_serial_sequence('public.${table}', 'id'), coalesce((select max(id) from public.${table}), 0) + 1, false)`
    );
    console.log(`${table}: sequência ajustada`);
  }

  console.log("\n--- Verificação (contagem no Neon após a carga) ---");
  let totalSource = 0;
  let totalNeon = 0;
  const mismatches = [];
  for (const table of TABLES) {
    const { rows } = await client.query(`select count(*)::int as n from public.${table}`);
    const neonCount = rows[0].n;
    const src = summary.find((s) => s.table === table)?.source ?? 0;
    totalSource += src;
    totalNeon += neonCount;
    if (neonCount !== src) mismatches.push({ table, src, neonCount });
  }
  console.log(`Total linhas na origem: ${totalSource}`);
  console.log(`Total linhas no Neon:   ${totalNeon}`);
  if (mismatches.length) {
    console.log("\nDIVERGÊNCIAS:");
    for (const m of mismatches) console.log(`  ${m.table}: origem=${m.src} neon=${m.neonCount}`);
    process.exitCode = 1;
  } else {
    console.log("\nTodas as tabelas batem certinho.");
  }

  await client.end();
}

main().catch((err) => {
  console.error("Erro fatal:", err);
  process.exitCode = 1;
});
